-- Order management schema (Oracle 19c)
CREATE SEQUENCE ORDERS_SEQ START WITH 1000 INCREMENT BY 1 NOCACHE;
CREATE SEQUENCE ORDER_LINES_SEQ START WITH 1 INCREMENT BY 1 CACHE 50;

CREATE TABLE CUSTOMERS (
  CUSTOMER_ID   NUMBER(19)      PRIMARY KEY,
  NAME          VARCHAR2(200)   NOT NULL,
  EMAIL         VARCHAR2(320),
  SEGMENT       VARCHAR2(30),
  CREDIT_LIMIT  NUMBER(12,2),
  IS_ACTIVE     NUMBER(1)       DEFAULT 1 NOT NULL CHECK (IS_ACTIVE IN (0, 1))
);

CREATE TABLE ORDERS (
  ORDER_ID      NUMBER(19)      PRIMARY KEY,
  ORDER_NO      VARCHAR2(20)    NOT NULL UNIQUE,
  CUSTOMER_ID   NUMBER(19)      NOT NULL REFERENCES CUSTOMERS (CUSTOMER_ID),
  STATUS        VARCHAR2(20)    NOT NULL,
  TOTAL_AMT     NUMBER(12,2)    NOT NULL,
  CREATED_AT    DATE            DEFAULT SYSDATE NOT NULL,
  NOTES         LONG
);

CREATE TABLE ORDER_LINES (
  LINE_ID       NUMBER(19)      PRIMARY KEY,
  ORDER_ID      NUMBER(19)      NOT NULL REFERENCES ORDERS (ORDER_ID),
  SKU           VARCHAR2(40)    NOT NULL,
  QTY           NUMBER(6)       NOT NULL,
  UNIT_PRICE    NUMBER(12,2)    NOT NULL
);

CREATE TABLE ORDER_AUDIT (
  AUDIT_ID      NUMBER(19)      GENERATED BY DEFAULT ON NULL AS IDENTITY,
  ORDER_ID      NUMBER(19)      NOT NULL,
  OLD_STATUS    VARCHAR2(20),
  NEW_STATUS    VARCHAR2(20),
  CHANGED_BY    VARCHAR2(60),
  CHANGED_AT    TIMESTAMP       DEFAULT SYSTIMESTAMP
);

CREATE INDEX ORDERS_STATUS_IX ON ORDERS (STATUS, CREATED_AT);
